CREATE ROLE anon;CREATE ROLE authenticated;CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;CREATE SCHEMA smarter_private;
CREATE FUNCTION auth.uid()RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.viewer',true),'')::uuid$$;
CREATE FUNCTION auth.role()RETURNS text LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.authrole',true),'')$$;
CREATE FUNCTION public.fn_club_cashier_scope(uuid)RETURNS text LANGUAGE sql STABLE AS $$SELECT coalesce(nullif(current_setting('test.scope',true),''),'club')$$;
CREATE FUNCTION public.fn_can_read_club_member_data(uuid,uuid)RETURNS boolean LANGUAGE sql STABLE AS $$SELECT coalesce(current_setting('test.canread',true),'on')<>'off'$$;
CREATE FUNCTION public.fn_is_union_overseer(uuid,uuid)RETURNS boolean LANGUAGE sql STABLE AS $$SELECT false$$;
CREATE TABLE public.profiles(id uuid PRIMARY KEY,is_admin boolean);
CREATE TABLE public.agents(id uuid PRIMARY KEY);
CREATE TABLE public.club_members(user_id uuid,club_id uuid,role text,agent_id uuid,status text);
CREATE TABLE public.club_member_daily_facts_state(singleton boolean,initialized boolean);
INSERT INTO public.club_member_daily_facts_state VALUES(true,true);
CREATE TABLE public.club_member_daily_facts(club_id uuid,user_id uuid,played_on date,game_variant text,is_mtt boolean,hands bigint,wins bigint,vpip_hands bigint,pfr_hands bigint,tb_hands bigint,faced_tb bigint,folded_tb bigint,cb_hands bigint,cb_opps bigint,fees numeric,net numeric);
CREATE TABLE public.member_record_daily_facts(LIKE public.club_member_daily_facts,accounting_cutoff timestamptz);
CREATE INDEX ON public.member_record_daily_facts(club_id,user_id,played_on);
CREATE TABLE public.ca_hand_facts(hand_id uuid,user_id uuid,club_id uuid,table_id uuid,tournament_id uuid,played_at timestamptz,game_variant text,net numeric,rake_paid numeric,PRIMARY KEY(hand_id,user_id));
CREATE INDEX ca_hand_facts_cash_member_time_idx ON public.ca_hand_facts(user_id,played_at)WHERE tournament_id IS NULL;
CREATE TABLE public.cash_participant_funding_receipts(id uuid,operation_kind text,table_id uuid,account_entity_id uuid,funding_club_id uuid,seat_joined_at timestamptz,recorded_at timestamptz);
CREATE INDEX ON public.cash_participant_funding_receipts(table_id,account_entity_id,seat_joined_at DESC,recorded_at DESC,id DESC)WHERE operation_kind='buyin';
CREATE TABLE public.tournament_players(tournament_id uuid,user_id uuid,club_id uuid);
CREATE TABLE public.ca_launch_accounting_boundaries(scope_kind text,scope_id uuid,cutoff_at timestamptz,undone_at timestamptz);
CREATE TABLE public.chip_ledger(id uuid,club_id uuid,to_entity_id uuid,from_entity_id uuid,to_type text,from_type text,tournament_id uuid,status text,amount numeric,created_at timestamptz);
CREATE INDEX ON public.chip_ledger(club_id,to_entity_id,created_at);
CREATE INDEX ON public.chip_ledger(club_id,from_entity_id,created_at);
CREATE FUNCTION smarter_private.original_inventory_proof_sources_match()RETURNS boolean LANGUAGE sql STABLE AS $$SELECT coalesce(current_setting('test.source65',true),'on')<>'off'$$;
CREATE FUNCTION smarter_private.original_inventory_basis_generation()RETURNS text LANGUAGE sql STABLE AS $$SELECT 'native-source65-adapter'::text$$;
CREATE FUNCTION public.fn_ca_break_window_refuses_migrations(timestamptz)RETURNS text LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.ddl_refusal',true),'')$$;
CREATE FUNCTION public.fn_platform_frozen()RETURNS boolean LANGUAGE sql STABLE AS $$SELECT coalesce(current_setting('test.frozen',true),'off')='on'$$;
CREATE FUNCTION public.fn_active_maintenance_release_boundary()RETURNS timestamptz LANGUAGE sql STABLE AS $$SELECT NULL::timestamptz$$;
